package com.hs.jxc.fin.closing;

import com.hs.jxc.common.api.*;
import com.hs.jxc.common.audit.AuditWriter;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.common.db.*;
import com.hs.jxc.common.idempotency.IdempotencyExecutor;
import com.hs.jxc.fin.accounting.AccountingService;
import com.hs.jxc.fin.api.*;
import com.hs.jxc.fin.service.BookResolver;
import com.hs.jxc.sys.api.Access;
import com.hs.jxc.sys.service.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.function.Function;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** All close/waive/reopen decisions are recomputed after taking the exclusive book gate. */
@Service
public class ClosingService {
    private static final Set<String> WAIVABLE=Set.of("AR_DIFF","AP_DIFF","INV_DIFF","CASH_DIFF");
    private final JdbcTemplate db;private final JsonCodec json;private final AuthorizationService auth;private final FieldPolicyService fields;private final BookResolver books;private final BookGate gates;private final IdempotencyExecutor idem;private final AuditWriter audit;private final LedgerApi ledger;private final AccountingService accounting;private final ObjectProvider<ReportApi> reports;private final List<FinancialSourceProvider> sources;private final SnapshotService snapshots;private final TransactionTemplate tx;
    public ClosingService(JdbcTemplate db,JsonCodec json,AuthorizationService auth,FieldPolicyService fields,BookResolver books,BookGate gates,IdempotencyExecutor idem,AuditWriter audit,LedgerApi ledger,AccountingService accounting,ObjectProvider<ReportApi> reports,List<FinancialSourceProvider> sources,SnapshotService snapshots,PlatformTransactionManager tm){this.db=db;this.json=json;this.auth=auth;this.fields=fields;this.books=books;this.gates=gates;this.idem=idem;this.audit=audit;this.ledger=ledger;this.accounting=accounting;this.reports=reports;this.sources=sources;this.snapshots=snapshots;this.tx=new TransactionTemplate(tm);}
    private static long n(Map<String,Object> row,String k){return ((Number)row.get(k)).longValue();}
    private static int generation(Map<String,Object> period){return ((Number)period.get("closeGeneration")).intValue();}
    private Map<String,Object> period(Access a,long id,boolean lock){var rows=db.queryForList("SELECT * FROM fin_period WHERE country_id=? AND id=?"+(lock?" FOR UPDATE":""),a.requireCountry(),id);if(rows.isEmpty())throw ApiException.notFound();var p=DbRows.camel(rows.getFirst());books.resolve(a,n(p,"bookId"),null);p.put("name",p.get("fiscalYear")+"-"+String.format("%02d",((Number)p.get("periodNo")).intValue()));return p;}
    private void readable(Access a){for(String group:List.of("COST","ORDER_TOTAL","PROFIT"))if(FieldPolicyService.rank(a.fieldGroups().get(group))<1)throw ApiException.forbidden();}
    private Map<String,Object> command(RequestContext c,long id,String action,Map<String,Object> body,String key,Function<Access,Map<String,Object>> work){return tx.execute(status->{var a=auth.authorize(c);a.require(action.equals("reopen")?"fin:period:reopen":"fin:period:close");readable(a);var p=period(a,id,false);long book=n(p,"bookId");if(body.get("bookId")!=null&&Inputs.id(body.get("bookId"))!=book)throw ApiException.notFound();gates.lock(a.requireCountry(),book,true);return fields.mask(a,idem.execute(c,"POST","/api/v1/fin/periods/"+id+"/"+action,key,body,book,()->work.apply(a),r->{books.resolve(a,book,null);readable(a);}),"COST");});}
    public Map<String,Object> check(RequestContext c,long id,Map<String,Object> body,String key){return command(c,id,"close-check",body,key,a->checkResult(a,period(a,id,true)));}
    private Map<String,Object> checkResult(Access a,Map<String,Object> p){
        if("CLOSED".equals(p.get("status"))){var rows=db.queryForList("SELECT checks FROM fin_close_generation WHERE country_id=? AND book_id=? AND period_id=? AND close_generation=?",a.requireCountry(),p.get("bookId"),p.get("id"),generation(p));if(rows.isEmpty())throw new ApiException(409,"FIN_SNAPSHOT_MISSING","已结账期间缺少核对代次");return Map.of("bookId",p.get("bookId"),"period",p,"periodId",p.get("id"),"status",p.get("status"),"checks",json.read(rows.getFirst().get("checks").toString(),List.class),"canClose",false,"closeGeneration",generation(p),"source","CLOSED_SNAPSHOT");}
        var prepared=prepare(a,p);return publicCheck(p,prepared);
    }
    private record Prepared(List<Map<String,Object>> checks,Map<String,Object> balance,Map<String,Object> report,List<Map<String,Object>> reconcile,Map<String,Object> sourceVersions,String fingerprint,int generation){}
    private Map<String,Object> publicCheck(Map<String,Object> p,Prepared x){return Map.of("bookId",p.get("bookId"),"period",p,"periodId",p.get("id"),"status",p.get("status"),"checks",x.checks(),"canClose",Set.of("OPEN","PENDING_CLOSE").contains(p.get("status"))&&x.checks().stream().noneMatch(r->"FAIL".equals(r.get("result"))),"closeGeneration",x.generation(),"sourceFingerprint",x.fingerprint());}
    private List<Map<String,Object>> rows(String sql,Object... args){return db.queryForList(sql,args).stream().map(DbRows::camel).toList();}
    private Prepared prepare(Access a,Map<String,Object> p){
        long book=n(p,"bookId"),period=n(p,"id");int next=generation(p)+1;LocalDate start=LocalDate.parse(p.get("startDate").toString()),end=LocalDate.parse(p.get("endDate").toString());
        var vouchers=rows("SELECT id,voucher_no,status,version,total_debit,total_credit FROM fin_voucher WHERE country_id=? AND book_id=? AND period_id=? ORDER BY id",a.requireCountry(),book,period);
        var events=rows("SELECT e.id,e.event_type,e.source_type,e.source_id,e.event_seq,e.version,e.status,r.id result_id,r.status result_status,c.status consumer_status,c.version consumer_version,c.last_error FROM sys_biz_event e LEFT JOIN fin_event_result r ON r.country_id=e.country_id AND r.event_id=e.id LEFT JOIN sys_biz_event_consume c ON c.country_id=e.country_id AND c.event_id=e.id AND c.consumer='FIN_VOUCHER' WHERE e.country_id=? AND e.book_id=? AND e.biz_date BETWEEN ? AND ? AND NOT(e.source_type='SYS_REPORT_EXPORT' AND e.event_type='SYS_REPORT_EXPORT_REQUESTED') ORDER BY e.id",a.requireCountry(),book,start,end);
        var unbalanced=rows("SELECT v.id,v.voucher_no FROM fin_voucher v LEFT JOIN fin_voucher_line l ON l.country_id=v.country_id AND l.voucher_id=v.id WHERE v.country_id=? AND v.book_id=? AND v.period_id=? GROUP BY v.id HAVING count(l.id)<2 OR v.total_debit<>v.total_credit OR coalesce(sum(l.debit),0)<>coalesce(sum(l.credit),0) OR coalesce(sum(l.debit),0)<>v.total_debit OR coalesce(sum(l.credit),0)<>v.total_credit ORDER BY v.id",a.requireCountry(),book,period);
        var balances=ledger.balances(a,book,period);var lines=ledger.postedLines(a,book,period);var reconcile=accounting.reconcileForClose(a,book,period);
        var report=reports.getObject().snapshot(a,book,period);var structural=new ArrayList<Map<String,Object>>();for(var source:sources)structural.addAll(source.closingIssues(a,book,end));
        var sourceVersions=new LinkedHashMap<String,Object>();sourceVersions.put("bookId",book);sourceVersions.put("periodId",period);sourceVersions.put("periodVersion",p.get("version"));sourceVersions.put("closeGeneration",next);sourceVersions.put("events",events);sourceVersions.put("vouchers",vouchers);sourceVersions.put("accounts",rows("SELECT * FROM fin_account WHERE country_id=? AND book_id=? ORDER BY id",a.requireCountry(),book).stream().map(r->{r.put("auxTypes",json.read(r.get("auxTypes").toString(),List.class));return r;}).toList());sourceVersions.put("balances",balances);sourceVersions.put("postedLines",lines);sourceVersions.put("reconcile",reconcile);sourceVersions.put("report",report);sourceVersions.put("structuralIssues",structural);
        String fingerprint=Digests.sha256(json.write(IdempotencyExecutor.canonical(sourceVersions)));var checks=new ArrayList<Map<String,Object>>();
        add(a,p,checks,next,fingerprint,"UNPOSTED","本期没有未审核或未记账的凭证",vouchers.stream().filter(v->!Set.of("POSTED","REVERSED").contains(v.get("status"))).toList(),false);
        add(a,p,checks,next,fingerprint,"UNBALANCED","没有借贷不平的凭证",unbalanced,false);
        add(a,p,checks,next,fingerprint,"EVENTS_OPEN","本期业务事件均已有完成的会计解释",events.stream().filter(e->e.get("resultId")==null||"FAILED".equals(e.get("status"))||"FAILED".equals(e.get("consumerStatus"))).toList(),false);
        for(String code:List.of("COST_PENDING","ALLOCATION_PENDING","STOCKTAKE_PENDING")){var details=structural.stream().filter(r->code.equals(r.get("checkCode"))).toList();add(a,p,checks,next,fingerprint,code,switch(code){case "COST_PENDING"->"没有缺成本或汇率的来源";case "ALLOCATION_PENDING"->"没有未确认的分摊";default->"没有未过账的盘点调整";},details,false);}
        // Every unknown owner blocker stays structural; future source modules cannot silently weaken closing.
        for(var issue:structural)if(!Set.of("COST_PENDING","ALLOCATION_PENDING","STOCKTAKE_PENDING").contains(issue.get("checkCode")))add(a,p,checks,next,fingerprint,Objects.toString(issue.get("checkCode")),Objects.toString(issue.get("message")),List.of(issue),false);
        add(a,p,checks,next,fingerprint,"RECON_DATA_MISSING","核对成本、汇率及分摊资料完整",reconcile.stream().filter(r->Boolean.TRUE.equals(r.get("incomplete"))||r.get("diffAmount")==null).toList(),false);
        for(var r:reconcile){String code="INVENTORY".equals(r.get("type"))?"INV_DIFF":r.get("type")+"_DIFF";boolean complete=!Boolean.TRUE.equals(r.get("incomplete"))&&r.get("diffAmount")!=null;boolean zero=complete&&new BigDecimal(r.get("diffAmount").toString()).signum()==0;add(a,p,checks,next,fingerprint,code,"子账与总账核对："+r.get("type"),zero?List.of():List.of(r),complete);}
        add(a,p,checks,next,fingerprint,"CASHFLOW_MISSING","现金及银行分录都有现金流项目",lines.stream().filter(l->(Boolean.TRUE.equals(l.get("isCash"))||Boolean.TRUE.equals(l.get("isBank")))&&l.get("cashflowItemId")==null).toList(),false);
        add(a,p,checks,next,fingerprint,"REPORT_CONFIG","三张报表配置完整",report.entrySet().stream().filter(e->!(e.getValue() instanceof Map<?,?> r)||!Boolean.TRUE.equals(r.get("available"))).map(e->Map.of("reportType",e.getKey(),"detail",e.getValue())).toList(),false);
        var following=rows("SELECT id,start_date,status FROM fin_period WHERE country_id=? AND book_id=? AND start_date=?",a.requireCountry(),book,end.plusDays(1));boolean natural=start.getDayOfMonth()==1&&end.equals(start.withDayOfMonth(start.lengthOfMonth()));
        add(a,p,checks,next,fingerprint,"NEXT_PERIOD","下一期间日期连续并可开放",following.isEmpty()&&natural?List.of():following.size()==1&&Set.of("OPEN","NOT_STARTED").contains(following.getFirst().get("status"))?List.of():List.of(Map.of("code",following.isEmpty()?"FIN_NEXT_PERIOD_REQUIRED":"FIN_NEXT_PERIOD_NOT_OPEN")),false);
        return new Prepared(checks,Map.of("balances",balances,"postedLines",lines),report,reconcile,sourceVersions,fingerprint,next);
    }
    private void add(Access a,Map<String,Object> p,List<Map<String,Object>> checks,int generation,String source,String code,String message,List<?> failures,boolean waivable){
        String fingerprint=Digests.sha256(source+"/"+generation+"/"+code+"/"+json.write(IdempotencyExecutor.canonical(failures)));var row=new LinkedHashMap<String,Object>();row.put("checkCode",code);row.put("message",message);row.put("detail",failures);row.put("fingerprint",fingerprint);row.put("closeGeneration",generation);row.put("waivable",waivable&&WAIVABLE.contains(code)&&!failures.isEmpty());row.put("result",failures.isEmpty()?"PASS":"FAIL");
        if(!failures.isEmpty()&&waivable&&WAIVABLE.contains(code)){var waived=rows("SELECT id,reason,waived_by,created_at FROM fin_close_waiver WHERE country_id=? AND book_id=? AND period_id=? AND close_generation=? AND check_code=? AND fingerprint=? ORDER BY id DESC LIMIT 1",a.requireCountry(),p.get("bookId"),p.get("id"),generation,code,fingerprint);if(!waived.isEmpty()){row.put("result","WAIVED");row.put("waiveReason",waived.getFirst().get("reason"));row.put("waiver",waived.getFirst());}}
        checks.add(row);
    }
    public Map<String,Object> waive(RequestContext c,long id,Map<String,Object> body,String key){return command(c,id,"waive",body,key,a->{var p=period(a,id,true);if("CLOSED".equals(p.get("status")))throw new ApiException(400,"FIN_PERIOD_CLOSED","已结账期间不能确认差异");String code=Inputs.required(body,"checkCode");if(!WAIVABLE.contains(code))throw Inputs.bad("结构缺项不能豁免");String reason=Inputs.required(body,"reason");if(reason.length()>1000)throw Inputs.bad("原因不能超过1000字");var x=prepare(a,p);var check=x.checks().stream().filter(r->code.equals(r.get("checkCode"))).findFirst().orElseThrow(()->Inputs.bad("核对项不合法"));if(!Boolean.TRUE.equals(check.get("waivable")))throw Inputs.bad("该核对项不能确认差异");if(!Objects.equals(body.get("fingerprint"),check.get("fingerprint"))||body.get("closeGeneration")==null||Inputs.id(body.get("closeGeneration"))!=x.generation())throw new ApiException(409,"FIN_WAIVER_STALE","来源或代次已变化，请重新核对");db.update("INSERT INTO fin_close_waiver(country_id,book_id,period_id,close_generation,check_code,fingerprint,reason,waived_by) VALUES(?,?,?,?,?,?,?,?)",a.requireCountry(),p.get("bookId"),id,x.generation(),code,check.get("fingerprint"),reason,a.userId());audit.append(c,"确认结账差异","fin-period",id,null,Map.of("checkCode",code,"fingerprint",check.get("fingerprint"),"reason",reason,"closeGeneration",x.generation()));return checkResult(a,p);});}
    public Map<String,Object> close(RequestContext c,long id,Map<String,Object> body,String key){return command(c,id,"close",body,key,a->{var p=period(a,id,true);long book=n(p,"bookId");if("CLOSED".equals(p.get("status")))return closedResult(a,p,true,null);if(!Set.of("OPEN","PENDING_CLOSE").contains(p.get("status")))throw new ApiException(400,"FIN_PERIOD_NOT_OPEN","期间尚未开放");var x=prepare(a,p);if(x.checks().stream().anyMatch(r->"FAIL".equals(r.get("result"))))throw new ApiException(400,"FIN_CLOSE_BLOCKED","结账检查未通过",publicCheck(p,x));int generation=db.queryForObject("SELECT jxc_finalize_period(?,?,?,?,?::jsonb,?::jsonb,?::jsonb,?::jsonb,?,?::jsonb)",Integer.class,a.requireCountry(),book,id,a.userId(),json.write(x.balance()),json.write(x.report()),json.write(Map.of("rows",x.reconcile())),json.write(x.sourceVersions()),x.fingerprint(),json.write(x.checks()));var next=next(a,book,p);ledger.initializePeriod(a,book,n(next,"id"));var closed=period(a,id,false);audit.append(c,"结账","fin-period",id,p,Map.of("closeGeneration",generation,"sourceFingerprint",x.fingerprint()));return closedResult(a,closed,false,x.checks());});}
    private Map<String,Object> next(Access a,long book,Map<String,Object> p){var rows=rows("SELECT * FROM fin_period WHERE country_id=? AND book_id=? AND start_date=?",a.requireCountry(),book,LocalDate.parse(p.get("endDate").toString()).plusDays(1));return rows.isEmpty()?Map.of():rows.getFirst();}
    private Map<String,Object> closedResult(Access a,Map<String,Object> p,boolean duplicate,List<Map<String,Object>> checks){var out=new LinkedHashMap<String,Object>();out.put("bookId",p.get("bookId"));out.put("period",p);out.put("closeGeneration",generation(p));out.put("snapshots",snapshots.generation(a,n(p,"bookId"),n(p,"id"),generation(p)));out.put("nextPeriod",next(a,n(p,"bookId"),p));out.put("duplicate",duplicate);out.put("checks",checks==null?checkResult(a,p).get("checks"):checks);return out;}
    public Map<String,Object> impact(RequestContext c,long id,Long selected){return tx.execute(status->{var a=auth.authorize(c);a.require("fin:period:reopen");readable(a);var p=period(a,id,false);if(selected!=null&&selected!=n(p,"bookId"))throw ApiException.notFound();return fields.mask(a,impact(a,p),"COST");});}
    private Map<String,Object> impact(Access a,Map<String,Object> p){long book=n(p,"bookId");var dependencies=new ArrayList<Map<String,Object>>();var closed=new ArrayList<Map<String,Object>>();for(var later:rows("SELECT id,fiscal_year,period_no,start_date,end_date,status,version FROM fin_period WHERE country_id=? AND book_id=? AND start_date>? ORDER BY start_date",a.requireCountry(),book,LocalDate.parse(p.get("endDate").toString()))){var row=new LinkedHashMap<String,Object>(later);row.put("periodId",later.get("id"));row.put("voucherIds",db.queryForList("SELECT id FROM fin_voucher WHERE country_id=? AND book_id=? AND period_id=? AND status IN ('POSTED','REVERSED') ORDER BY id",Long.class,a.requireCountry(),book,later.get("id")));row.put("balances",rows("SELECT account_id,aux_key,currency,opening_debit,opening_credit,version FROM fin_account_balance WHERE country_id=? AND book_id=? AND period_id=? ORDER BY account_id,aux_key,currency",a.requireCountry(),book,later.get("id")));if("CLOSED".equals(later.get("status")))closed.add(row);else if("OPEN".equals(later.get("status")))dependencies.add(row);}
        return Map.of("bookId",book,"period",p,"dependencies",dependencies,"closedDependencies",closed,"snapshotRefs",snapshots.generation(a,book,n(p,"id"),generation(p)).stream().map(r->Map.of("id",r.get("id"),"snapshotType",r.get("snapshotType"),"closeGeneration",r.get("closeGeneration"))).toList(),"canReopen","CLOSED".equals(p.get("status"))&&closed.isEmpty());}
    public Map<String,Object> reopen(RequestContext c,long id,Map<String,Object> body,String key){return command(c,id,"reopen",body,key,a->{String reason=Inputs.required(body,"reason");if(reason.length()>1000)throw Inputs.bad("原因不能超过1000字");var p=period(a,id,true);if(!"CLOSED".equals(p.get("status")))throw new ApiException(400,"FIN_PERIOD_NOT_CLOSED","只有已结账期间可以反结账");var before=impact(a,p);if(!((List<?>)before.get("closedDependencies")).isEmpty())throw new ApiException(400,"FIN_LATER_CLOSED","后续期间仍已结账",before);long log=db.queryForObject("SELECT jxc_reopen_period(?,?,?,?,?,?::jsonb)",Long.class,a.requireCountry(),p.get("bookId"),id,a.userId(),reason,json.write(before.get("dependencies")));
        // Amounts already follow immutable posted facts. Invalidate cached versions and validate
        // every open dependent projection; later posting continues the existing carry-forward path.
        db.update("UPDATE fin_account_balance b SET version=b.version+1 FROM fin_period p WHERE p.country_id=b.country_id AND p.id=b.period_id AND b.country_id=? AND b.book_id=? AND p.start_date>? AND p.status='OPEN'",a.requireCountry(),p.get("bookId"),LocalDate.parse(p.get("endDate").toString()));
        var record=rows("SELECT * FROM fin_reopen_log WHERE country_id=? AND id=?",a.requireCountry(),log).getFirst();var result=new LinkedHashMap<String,Object>();result.put("bookId",p.get("bookId"));result.put("period",period(a,id,false));result.put("previousGeneration",generation(p));result.put("snapshotRefs",before.get("snapshotRefs"));result.put("dependencies",before.get("dependencies"));result.put("dependenciesAfter",impact(a,period(a,id,false)).get("dependencies"));result.put("projectionValidation","FACT_VALIDATED");result.put("invalidatedWaivers",json.read(record.get("invalidatedWaiverIds").toString(),List.class));result.put("reopenLogId",log);audit.append(c,"反结账","fin-period",id,p,result);return result;});}
}
